package com.infinitylibrary.rentals;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.community.*;
import com.infinitylibrary.gui.LibraryMenu;
import com.infinitylibrary.model.*;
import com.infinitylibrary.writing.BookDraft;
import com.google.gson.Gson;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.block.ChiseledBookshelf;
import org.bukkit.entity.Player;
import org.bukkit.event.block.Action;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.BookMeta;
import org.bukkit.persistence.PersistentDataType;
import io.papermc.paper.registry.data.dialog.input.DialogInput;
import net.kyori.adventure.text.Component;
import java.util.*;

/** Managed copies, not item transfers: an archive operation can neither lose nor duplicate inventory. */
public final class RentalVaultManager {
 public record Book(UUID id,UUID lease,UUID contributor,String title,String author,List<String> pages,boolean draft){public Book{Objects.requireNonNull(id);Objects.requireNonNull(lease);Objects.requireNonNull(contributor);if(title==null||title.length()>128||author==null||author.length()>64||pages.isEmpty()||pages.size()>100||pages.stream().anyMatch(p->p==null||p.length()>1024))throw new IllegalArgumentException("Book exceeds archive page/title limits");pages=List.copyOf(pages);}}
 private static final Gson JSON=new Gson();private final InfinityLibraryPlugin plugin;private Map<UUID,Book> books=Map.of();private final NamespacedKey display;private int task=-1,cursor;
 public RentalVaultManager(InfinityLibraryPlugin plugin){this.plugin=plugin;display=new NamespacedKey(plugin,"rental_shelf_display");load();task=Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,()->{var rooms=plugin.getGenerationEngine().navigationRooms().stream().filter(n->n.type()==RoomType.RENTABLE).toList();if(!rooms.isEmpty())refresh(rooms.get(Math.floorMod(cursor++,rooms.size())).id());},20,20);}
 public void shutdown(){if(task!=-1)Bukkit.getScheduler().cancelTask(task);}
 public void load(){var y=AtomicYaml.read(plugin.getDataFolder().toPath().resolve("rental-books.yml"));if(y.contains("schema")&&y.getInt("schema")!=1)throw new IllegalArgumentException("Unsupported rental book schema");Map<UUID,Book> next=new LinkedHashMap<>();for(String row:y.getStringList("books")){Book b=JSON.fromJson(row,Book.class);if(next.put(b.id(),b)!=null)throw new IllegalArgumentException("Duplicate archived book");}books=Map.copyOf(next);}
 private void persist(Map<UUID,Book> next){var y=new org.bukkit.configuration.file.YamlConfiguration();y.set("schema",1);y.set("books",next.values().stream().map(JSON::toJson).toList());AtomicYaml.write(plugin.getDataFolder().toPath().resolve("rental-books.yml"),y);books=Map.copyOf(next);}
 public List<Book> books(Player p,UUID lease){plugin.getRentalManager().get(p,lease);return books.values().stream().filter(b->b.lease().equals(lease)).sorted(Comparator.comparing(Book::title).thenComparing(Book::id)).toList();}
 public List<Book> visible(Player p){Set<UUID> accessible=new HashSet<>();plugin.getRentalManager().visible(p).forEach(l->accessible.add(l.id()));return books.values().stream().filter(b->accessible.contains(b.lease())).toList();}
 public Book get(Player p,UUID id){Book b=books.get(id);if(b==null)throw new IllegalArgumentException("Archived book not found");plugin.getRentalManager().get(p,b.lease());return b;}
 private Book add(Player p,UUID lease,String title,String author,List<String> pages,boolean draft){var l=plugin.getRentalManager().get(p,lease);if(!plugin.getRentalManager().activeHere(l))throw new IllegalArgumentException("Archived rentals are read-only; claim a new room to store new work");if(books(p,lease).size()>=64)throw new IllegalArgumentException("Maximum 64 archived books per workspace");Book b=new Book(UUID.randomUUID(),lease,p.getUniqueId(),title,author,pages,draft);Map<UUID,Book> next=new LinkedHashMap<>(books);next.put(b.id(),b);persist(next);refresh(l.room());return b;}
 public Book archiveHeld(Player p,UUID lease){ItemStack item=p.getInventory().getItemInMainHand();if((item.getType()!=Material.WRITTEN_BOOK&&item.getType()!=Material.WRITABLE_BOOK)||!(item.getItemMeta() instanceof BookMeta meta))throw new IllegalArgumentException("Hold a book or book & quill");if(plugin.getNativeBookEditor().temporary(item)||meta.getPersistentDataContainer().has(display,PersistentDataType.BYTE))throw new IllegalArgumentException("Finish the temporary writing session first");if(!plugin.getBookStorageManager().canRead(p,item))throw new IllegalArgumentException("This book belongs to another reader");String owner=meta.getPersistentDataContainer().get(new NamespacedKey(plugin,"book_owner_uuid"),PersistentDataType.STRING);if(owner!=null&&!owner.equals(p.getUniqueId().toString()))throw new IllegalArgumentException("You cannot archive another person's private manuscript");return add(p,lease,meta.hasTitle()?meta.getTitle():"Untitled draft",meta.hasAuthor()?meta.getAuthor():p.getName(),meta.getPages().isEmpty()?List.of(""):meta.getPages(),item.getType()==Material.WRITABLE_BOOK);}
 public Book archiveDraft(Player p,UUID lease){var d=plugin.getBookWritingManager().draft(p.getUniqueId());if(d.pages().stream().allMatch(String::isBlank))throw new IllegalArgumentException("Write something first");return add(p,lease,d.title().isBlank()?"Untitled draft":d.title(),p.getName(),d.pages(),true);}
 public void restoreDraft(Player p,UUID book){var b=get(p,book);var d=plugin.getBookWritingManager().draft(p.getUniqueId());if(!d.title().isBlank()||d.pages().stream().anyMatch(s->!s.isBlank()))throw new IllegalArgumentException("Your current manuscript is not empty. Archive it first, then start a new manuscript");var old=d.pages();d.replacePages(b.pages());d.details(b.title().substring(0,Math.min(32,b.title().length())),"general","",false);try{plugin.getBookWritingManager().save();}catch(RuntimeException ex){d.replacePages(old);d.details("","general","",false);throw ex;}plugin.getBookWritingManager().open(p);}
 private ItemStack readable(Book b){ItemStack item=new ItemStack(Material.WRITTEN_BOOK);BookMeta m=(BookMeta)item.getItemMeta();m.setTitle(b.title().substring(0,Math.min(32,b.title().length())));m.setAuthor(b.author());m.setPages(b.draft()?b.pages().stream().map(com.infinitylibrary.writing.BookTypography::render).toList():b.pages());item.setItemMeta(m);return item;}
 public void read(Player p,UUID id){plugin.getReadingManager().openRental(p,id);}
 public void readNative(Player p,UUID id){var b=get(p,id);p.closeInventory();p.openBook(readable(b));}
 public void delete(Player p,UUID id){Book b=get(p,id);var lease=plugin.getRentalManager().get(p,b.lease());if(!lease.owner().equals(p.getUniqueId())&&!b.contributor().equals(p.getUniqueId()))throw new IllegalArgumentException("Only the renter or contributor can delete this archived copy");var next=new LinkedHashMap<>(books);next.remove(id);persist(next);refresh(lease.room());}
 public boolean rental(Location at){return plugin.getGenerationEngine().roomAt(at).flatMap(r->plugin.getRoomManager().get(r.roomId())).map(r->r.type()==RoomType.RENTABLE).orElse(false);}
 public boolean canEnter(Player p,UUID room){if(p.hasPermission("infinitylibrary.admin"))return true;return plugin.getRentalManager().active(room).map(l->l.access(p.getUniqueId(),System.currentTimeMillis())).orElse(true);}
 public boolean blocked(Player p,Location location){return rental(location)&&plugin.getGenerationEngine().roomAt(location).map(r->!canEnter(p,r.instanceId())).orElse(false);}
 public boolean interact(Player p,Block block,Action action){if(block==null||!rental(block.getLocation()))return false;if(p.hasPermission("infinitylibrary.admin")&&plugin.getAuthoringManager().tool(p)!=null)return false;if(block.getType()==Material.CHISELED_BOOKSHELF||block.getType()==Material.LECTERN){if(action==Action.RIGHT_CLICK_BLOCK||action==Action.LEFT_CLICK_BLOCK){var room=plugin.getGenerationEngine().roomAt(block.getLocation()).orElseThrow();var lease=plugin.getRentalManager().active(room.instanceId());if(lease.isEmpty())browser(p,0);else try{workspace(p,lease.get().id());}catch(IllegalArgumentException ex){p.sendMessage("This room's workspace is private");}return true;}}if(blocked(p,block.getLocation())){p.sendMessage("This rental room is private");return true;}return false;}
 private List<Block> shelves(UUID roomId){var node=plugin.getGenerationEngine().navigationRooms().stream().filter(n->n.id().equals(roomId)).findFirst().orElse(null);if(node==null)return List.of();World world=plugin.getGenerationEngine().ensureWorld();var box=node.box();List<Block> result=new ArrayList<>();for(int x=box.origin().x()>>4;x<=(box.origin().x()+box.size().x()-1)>>4;x++)for(int z=box.origin().z()>>4;z<=(box.origin().z()+box.size().z()-1)>>4;z++)if(world.isChunkLoaded(x,z))for(var state:world.getChunkAt(x,z).getTileEntities())if(state.getType()==Material.CHISELED_BOOKSHELF&&box.contains(Vector3i.from(state.getLocation())))result.add(state.getBlock());result.sort(Comparator.comparingInt(Block::getX).thenComparingInt(Block::getY).thenComparingInt(Block::getZ));return result;}
 public void enforce(UUID room){for(Player p:Bukkit.getOnlinePlayers())if(plugin.getGenerationEngine().roomAt(p.getLocation()).map(r->r.instanceId().equals(room)).orElse(false)&&!canEnter(p,room)){p.closeInventory();p.leaveVehicle();p.teleport(plugin.getGenerationEngine().homeLocation());p.sendMessage("This rental workspace is now private");}}
 public void refresh(UUID room){var active=plugin.getRentalManager().active(room);int count=active.map(l->(int)books.values().stream().filter(b->b.lease().equals(l.id())).count()).orElse(0),next=0;for(Block block:shelves(room)){var state=(ChiseledBookshelf)block.getState();var inventory=state.getInventory();for(int i=0;i<6;i++){ItemStack old=inventory.getItem(i);boolean managed=old!=null&&old.hasItemMeta()&&old.getItemMeta().getPersistentDataContainer().has(display,PersistentDataType.BYTE);if(old!=null&&!managed)continue;if(next<count){ItemStack placeholder=new ItemStack(Material.WRITTEN_BOOK);BookMeta meta=(BookMeta)placeholder.getItemMeta();meta.setTitle("Private workspace");meta.setAuthor("Infinity Library");meta.setPages("Access private archived books through this shelf's rental workspace menu.");meta.getPersistentDataContainer().set(display,PersistentDataType.BYTE,(byte)1);placeholder.setItemMeta(meta);inventory.setItem(i,placeholder);next++;}else if(managed)inventory.setItem(i,null);}if(block.getBlockData() instanceof org.bukkit.block.data.type.ChiseledBookshelf data){for(int i=0;i<6;i++)data.setSlotOccupied(i,inventory.getItem(i)!=null);block.setBlockData(data,false);}}}
 public void trail(Player p,UUID id){Book b=get(p,id);var l=plugin.getRentalManager().get(p,b.lease());if(!plugin.getRentalManager().activeHere(l))throw new IllegalArgumentException("Archived books remain readable, but their rental has ended");var shelves=shelves(l.room());if(shelves.isEmpty())throw new IllegalArgumentException("No loaded chiseled bookshelf in that room. Navigate to the room first");int index=books(p,l.id()).indexOf(b);plugin.getNavigationManager().start(p,"private shelf: "+b.title(),shelves.get(Math.min(shelves.size()-1,index/6)).getLocation());}
 private void icon(LibraryMenu m,int slot,Material material,String title,String... lore){plugin.getBookWritingManager().icon(m.getInventory(),slot,material,title,lore);}
 public void browser(Player p,int page){var leases=plugin.getRentalManager().visible(p);page=Math.max(0,Math.min(page,Math.max(0,(leases.size()-1)/45)));LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.RENTALS,54,"Library • Rental workspaces");m.entry(53,""+page);for(int i=0;i<45&&page*45+i<leases.size();i++){var l=leases.get(page*45+i);m.entry(i,l.id().toString());icon(m,i,Material.OAK_DOOR,"Room "+l.room().toString().substring(0,8),plugin.getRentalManager().activeHere(l)?"Active private workspace":"Archived · owner records retained",l.owner().equals(p.getUniqueId())?"You are the renter":"Invited editor");}icon(m,45,Material.ARROW,"Previous");icon(m,47,Material.TRIPWIRE_HOOK,"Claim this room","Stand inside an unclaimed RENTABLE room","No payment · configured rental duration");icon(m,48,Material.COMPASS,"Find a rentable room");icon(m,49,Material.CHEST,"Player menu");icon(m,51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
 public void workspace(Player p,UUID id){var l=plugin.getRentalManager().get(p,id);LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.RENTAL_ROOM,27,"Library • Private workspace");m.entry(0,id.toString());icon(m,4,Material.OAK_DOOR,"Room "+l.room().toString().substring(0,8),plugin.getRentalManager().activeHere(l)?"Claim active":"Archive retained after expiry");icon(m,10,Material.CHISELED_BOOKSHELF,"Archived books and drafts");icon(m,12,Material.PAPER,"Private notes");icon(m,14,Material.PLAYER_HEAD,"Invite editor");icon(m,16,Material.CLOCK,"Renew claim");icon(m,18,Material.BARRIER,"Revoke editor");icon(m,20,Material.REDSTONE,"Release claim","Your archived work is retained");icon(m,22,Material.ARROW,"Workspaces");icon(m,24,Material.WRITABLE_BOOK,"Collaborative manuscripts");icon(m,26,Material.COMPASS,"Trail to this room");p.openInventory(m.getInventory());}
 public void bookBrowser(Player p,UUID lease,int page){var list=books(p,lease);page=Math.max(0,Math.min(page,Math.max(0,(list.size()-1)/45)));LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.RENTAL_BOOKS,54,"Library • Private books");m.entry(52,lease.toString());m.entry(53,""+page);for(int i=0;i<45&&page*45+i<list.size();i++){Book b=list.get(page*45+i);m.entry(i,b.id().toString());icon(m,i,b.draft()?Material.WRITABLE_BOOK:Material.WRITTEN_BOOK,b.title(),b.author(),"Private archived copy · original item stays with you");}icon(m,45,Material.ARROW,"Previous");icon(m,46,Material.BOOK,"Archive held book copy");icon(m,47,Material.FEATHER,"Archive current manuscript");icon(m,49,Material.OAK_DOOR,"Workspace");icon(m,50,Material.PAPER,"Start fresh manuscript","Requires confirmation · archive your work first");icon(m,51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
 private void bookMenu(Player p,UUID id){Book b=get(p,id);LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.RENTAL_BOOK,27,"Library • "+b.title());m.entry(0,id.toString());icon(m,4,Material.WRITTEN_BOOK,b.title());icon(m,10,Material.BOOK,"Read with saved progress");icon(m,11,Material.WRITTEN_BOOK,"Immersive book view","Page memory uses the guided reader");icon(m,12,Material.COMPASS,"Trail to bookshelf");icon(m,14,Material.WRITABLE_BOOK,"Restore into empty manuscript");icon(m,16,Material.BARRIER,"Delete archived copy");icon(m,22,Material.ARROW,"Private books");p.openInventory(m.getInventory());}
 private void notes(Player p,UUID id){noteBrowser(p,id,0);}
 private void noteBrowser(Player p,UUID id,int page){var lease=plugin.getRentalManager().get(p,id);page=Math.max(0,Math.min(page,Math.max(0,(lease.notes().size()-1)/45)));var m=new LibraryMenu(p,LibraryMenu.Screen.RENTAL_NOTES,54,"Library • Private notes");m.entry(52,id.toString());m.entry(53,""+page);for(int i=0;i<45&&page*45+i<lease.notes().size();i++){int index=page*45+i;m.entry(i,""+index);String text=lease.notes().get(index);icon(m,i,Material.PAPER,"Note "+(index+1),text.substring(0,Math.min(70,text.length())),"Open the complete note");}icon(m,45,Material.ARROW,"Previous");icon(m,47,Material.FEATHER,"Add note");icon(m,49,Material.OAK_DOOR,"Workspace");icon(m,51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
 private void confirm(Player p,String title,Runnable action,Runnable cancel){plugin.getManagedDialogs().show(p,title,"This action affects your workspace. Stored archives are separate from inventory items.",List.of(),List.of(new ManagedDialogs.Button("Confirm",r->action.run()),new ManagedDialogs.Button("Cancel",r->cancel.run())));}
 public void handle(Player p,LibraryMenu m,int slot){switch(m.screen()){
  case RENTALS->{int page=Integer.parseInt(m.entry(53));if(slot<45&&m.entry(slot)!=null)workspace(p,UUID.fromString(m.entry(slot)));else if(slot==45)browser(p,page-1);else if(slot==51)browser(p,page+1);else if(slot==49)plugin.getGuiManager().openMainMenu(p);else if(slot==48)plugin.getNavigationManager().destination(p,"rentable");else if(slot==47){var l=plugin.getRentalManager().claim(p);workspace(p,l.id());}}
  case RENTAL_NOTES->{UUID id=UUID.fromString(m.entry(52));int page=Integer.parseInt(m.entry(53));var lease=plugin.getRentalManager().get(p,id);if(slot<45&&m.entry(slot)!=null){int index=Integer.parseInt(m.entry(slot));String note=lease.notes().get(index);List<String> pages=new ArrayList<>();for(int n=0;n<note.length();n+=900)pages.add(note.substring(n,Math.min(note.length(),n+900)));if(pages.isEmpty())pages.add("");p.closeInventory();p.openBook(readable(new Book(UUID.randomUUID(),id,p.getUniqueId(),"Private note "+(index+1),"Workspace",pages,false)));}else if(slot==45)noteBrowser(p,id,page-1);else if(slot==51)noteBrowser(p,id,page+1);else if(slot==49)workspace(p,id);else if(slot==47)plugin.getManagedDialogs().form(p,"Private note",List.of(DialogInput.text("text",Component.text("Note")).maxLength(4000).multiline(io.papermc.paper.registry.data.dialog.input.TextDialogInput.MultilineOptions.create(100,160)).build()),r->{plugin.getRentalManager().editNote(p,id,r.getText("text"));noteBrowser(p,id,page);},()->noteBrowser(p,id,page));}
  case RENTAL_ROOM->{UUID id=UUID.fromString(m.entry(0));var l=plugin.getRentalManager().get(p,id);switch(slot){case 10->bookBrowser(p,id,0);case 12->notes(p,id);case 14,18->plugin.getManagedDialogs().form(p,slot==14?"Invite workspace editor":"Revoke editor",List.of(DialogInput.text("name",Component.text("Online player name or UUID")).maxLength(64).build()),r->{String name=r.getText("name");var online=Bukkit.getPlayerExact(name);UUID editor=online==null?UUID.fromString(name):online.getUniqueId();plugin.getRentalManager().manage(p,id,slot==14?"invite":"revoke",editor);workspace(p,id);},()->workspace(p,id));case 16->{plugin.getRentalManager().manage(p,id,"renew",null);workspace(p,id);}case 20->confirm(p,"Release this rental?",()->{plugin.getRentalManager().manage(p,id,"release",null);refresh(l.room());workspace(p,id);},()->workspace(p,id));case 22->browser(p,0);case 24->plugin.getCollaborationManager().browser(p,0);case 26->{if(!plugin.getRentalManager().activeHere(l))throw new IllegalArgumentException("This rental has ended");plugin.getNavigationManager().room(p,l.room());}}}
  case RENTAL_BOOKS->{UUID lease=UUID.fromString(m.entry(52));int page=Integer.parseInt(m.entry(53));plugin.getRentalManager().get(p,lease);if(slot<45&&m.entry(slot)!=null)bookMenu(p,UUID.fromString(m.entry(slot)));else switch(slot){case 45->bookBrowser(p,lease,page-1);case 51->bookBrowser(p,lease,page+1);case 49->workspace(p,lease);case 46->{archiveHeld(p,lease);bookBrowser(p,lease,page);}case 47->{archiveDraft(p,lease);bookBrowser(p,lease,page);}case 50->confirm(p,"Start an empty manuscript?",()->{var d=plugin.getBookWritingManager().draft(p.getUniqueId());var old=d.pages();var title=d.title();var category=d.category();var tags=d.tags();boolean visibility=d.publicBook();int current=d.current();d.replacePages(List.of(""));d.details("","general","",false);try{plugin.getBookWritingManager().save();}catch(RuntimeException ex){d.replacePages(old);d.move(current);d.details(title,category,tags,visibility);throw ex;}plugin.getBookWritingManager().open(p);},()->bookBrowser(p,lease,page));}}
  case RENTAL_BOOK->{UUID id=UUID.fromString(m.entry(0));Book b=get(p,id);switch(slot){case 10->read(p,id);case 11->readNative(p,id);case 12->trail(p,id);case 14->restoreDraft(p,id);case 16->confirm(p,"Delete this archived copy?",()->{delete(p,id);bookBrowser(p,b.lease(),0);},()->bookMenu(p,id));case 22->bookBrowser(p,b.lease(),0);}}
  default->throw new IllegalArgumentException("Not a rental menu");
 }}
}
